import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        long c1 = fs.nextLong();
        long c2 = fs.nextLong();
        String s = fs.next();

        int adults = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') adults++;
        }

        long best = Long.MAX_VALUE;
        int maxGroups = adults; // each group needs at least one adult

        for (int g = 1; g <= maxGroups; g++) {
            int base = n / g;
            int rem = n % g;
            long cost = (long) rem * groupCost(base + 1, c1, c2)
                      + (long) (g - rem) * groupCost(base, c1, c2);
            if (cost < best) best = cost;
        }

        System.out.println(best);
    }

    private static long groupCost(int x, long c1, long c2) {
        if (x <= 0) return 0;
        long t = x - 1L;
        return c1 + c2 * t * t;
    }

    // Fast scanner
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return "";
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

