public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long c1 = Long.parseLong(st.nextToken());
        long c2 = Long.parseLong(st.nextToken());
        String s = br.readLine().trim();

        int adults = 0;
        int pupils = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') adults++;
            else pupils++;
        }

        long best = Long.MAX_VALUE;

        // Try all possible numbers of groups from 1 to number of adults
        for (int g = 1; g <= adults; g++) {
            int baseAdults = adults / g;
            int extraAdultsGroups = adults % g; // these groups get baseAdults+1 adults
            int groupsWithBaseAdults = g - extraAdultsGroups;

            long minSize = baseAdults;          // groups with baseAdults adults
            long maxSize = baseAdults + 1;      // groups with baseAdults+1 adults

            long minCap = minSize;              // pupils capacity in min-size groups
            long maxCap = maxSize;              // pupils capacity in max-size groups

            long totalMinCap = minCap * groupsWithBaseAdults;
            long totalMaxCap = maxCap * extraAdultsGroups;
            long totalCap = totalMinCap + totalMaxCap;

            if (totalCap < pupils) continue; // not enough capacity to place all pupils

            long remainingPupils = pupils;

            // Fill groups with minSize first
            long useMin = Math.min(totalMinCap, remainingPupils);
            remainingPupils -= useMin;

            // Then fill groups with maxSize
            long useMax = Math.min(totalMaxCap, remainingPupils);
            remainingPupils -= useMax;

            if (remainingPupils > 0) continue; // should not happen due to capacity check

            long groupsMinFull = useMin / minCap;
            long groupsMaxFull = useMax / maxCap;

            long groupsMinPartial = (useMin % minCap == 0) ? 0 : 1;
            long groupsMaxPartial = (useMax % maxCap == 0) ? 0 : 1;

            long fullGroups = groupsMinFull + groupsMaxFull;
            long partialGroups = groupsMinPartial + groupsMaxPartial;

            long totalCost = fullGroups * (c1 + c2 * (long)(n / g) * (long)(n / g)); // placeholder

            // Recalculate exact cost using sizes:
            // For min-size groups
            long cost = 0;
            long pupilsLeft = pupils;

            // First fill groups with baseAdults adults
            for (int i = 0; i < groupsWithBaseAdults; i++) {
                long size = baseAdults;
                long canAdd = size; // pupils capacity
                long add = Math.min(canAdd, pupilsLeft);
                pupilsLeft -= add;
                size += add;
                cost += c1 + c2 * (size - 1) * (size - 1);
            }
            // Then groups with baseAdults+1 adults
            for (int i = 0; i < extraAdultsGroups; i++) {
                long size = baseAdults + 1;
                long canAdd = size;
                long add = Math.min(canAdd, pupilsLeft);
                pupilsLeft -= add;
                size += add;
                cost += c1 + c2 * (size - 1) * (size - 1);
            }

            if (cost < best) best = cost;
        }

        System.out.println(best);
    }
}

